<script setup>
import {MapPin,Clock3,ArrowUpRight,Users,Flower2} from 'lucide-vue-next'
import CardBossProgress from './CardBossProgress.vue'
import {priceValue,priceUnit} from '../card-pricing'
import {number,age,flowers,labels,features} from '../api'
defineProps({card:Object});const emit=defineEmits(['detail','apply'])
</script>
<template><article class="team-card"><div class="card-top"><span v-if="features.teammate_recruitment&&card.type==='team'" class="tag flower" :class="card.flower"><Flower2 :size="12"/>{{card.teammate_need==='dragon_knight'?'招募龙骑':card.teammate_need==='priest'?'招募祭司':flowers[card.flower]}}</span><span class="card-state" :class="card.status"><i></i>{{card.type==='boss'&&card.status==='active'?'求带中':labels[card.status]}}</span></div><button class="card-title" @click="emit('detail',card)"><h3>{{card.map_name}}</h3><ArrowUpRight :size="19"/></button><div class="card-sub"><span v-if="card.type==='team'"><Users :size="14"/> 招 {{card.boss_slots??(card.capacity-card.fighter_count-card.priest_count)}} 位老板</span><span>Lv. {{card.type==='team'?`${card.level_min}–${card.level_max}`:card.level}}</span></div><div class="card-metrics"><div><span>{{card.type==='boss'?'期望经验 / 小时':'预估经验 / 小时'}}</span><strong>{{number(card.exp_min)}}–{{number(card.exp_max)}}<small>万</small></strong></div><div><span>{{card.type==='boss'?'收费偏好':'收费'}}</span><strong class="price" :class="{'experience-price':card.price_mode==='experience'}">{{priceValue(card)}}<small v-if="card.price_mode!=='any'">{{priceUnit(card)}}</small></strong></div></div><div class="card-time"><Clock3 :size="14"/><span>{{card.start_time}} – {{card.end_time<=card.start_time?'次日 ':''}}{{card.end_time}}</span><small>北京时间</small></div><CardBossProgress v-if="card.type==='team'" :members="card.boss_progress||[]" :card-id="card.id"/><div class="card-bottom"><div><template v-if="card.type==='team'"><span class="seat-dots"><i v-for="n in card.capacity" :class="{open:n>card.capacity-card.remaining}"></i></span><span class="seat-label">{{card.remaining?'余 '+card.remaining+' 个老板位':'队伍已满'}}</span></template><template v-else><span class="avatar mini">{{card.game_id.slice(0,1)}}</span><span class="seat-label">{{card.game_id}}</span></template></div><button class="button card-cta" :disabled="card.status!=='active'" @click="emit('apply',card)">{{card.type==='team'?'申请上车':'认领老板'}}<ArrowUpRight :size="16"/></button></div><div class="card-foot"><span>{{age(card.created_at)}}</span><button @click="emit('detail',card)">详情与风险提示</button></div></article></template>
